  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: -5 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: 5.5 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine rejects unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.deepEqual(addLine(result.value, { sku: 'UNKNOWN-SKU', qty: 1 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine rejects draft status requirement', () => {
  const nonDraftInvoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(addLine(nonDraftInvoice, { sku: 'DEV-HOUR', qty: 1 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the input invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const originalLength = result.value.lines.length;
  addLine(result.value, { sku: 'DEV-HOUR', qty: 10 });
  assert.equal(result.value.lines.length, originalLength);
});

test('removeLine removes a line from an invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  assert.equal(result.ok, true);
  const removeResult = removeLine(result.value, 'DES-HOUR');
  assert.equal(removeResult.ok, true);
  assert.equal(removeResult.value.lines.length, 1);
  assert.equal(removeResult.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine returns LINE_NOT_FOUND for unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.deepEqual(removeLine(result.value, 'UNKNOWN-SKU'), { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine returns NO_LINES when removing the last line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.deepEqual(removeLine(result.value, 'DES-HOUR'), { ok: false, error: 'NO_LINES' });
});

test('removeLine rejects draft status requirement', () => {
  const nonDraftInvoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 },
    ],
  };
  assert.deepEqual(removeLine(nonDraftInvoice, 'DEV-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate the input invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  assert.equal(result.ok, true);
  const originalLength = result.value.lines.length;
  removeLine(result.value, 'DES-HOUR');
  assert.equal(result.value.lines.length, originalLength);
});

test('addLine and removeLine can be chained', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const added = addLine(result.value, { sku: 'DEV-HOUR', qty: 10 });
  assert.equal(added.ok, true);
  const removed = removeLine(added.value, 'DES-HOUR');
  assert.equal(removed.ok, true);
  assert.equal(removed.value.lines.length, 1);
  assert.equal(removed.value.lines[0].sku, 'DEV-HOUR');
});

test('issueInvoice assigns a number and marks as issued', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const issueResult = issueInvoice(result.value, []);
  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2024-0001');
  assert.equal(issueResult.value.status, 'issued');
});

test('issueInvoice increments the number based on existing numbers', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const existing = ['INV-2024-0001', 'INV-2024-0002'];
  const issueResult = issueInvoice(result.value, existing);
  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2024-0003');
});

test('issueInvoice rejects a non-draft invoice', () => {
  const nonDraftInvoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(issueInvoice(nonDraftInvoice, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the input invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'draft');
  issueInvoice(result.value, []);
  assert.equal(result.value.status, 'draft');
});

test('issueInvoice preserves invoice data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  assert.equal(result.ok, true);
  const issueResult = issueInvoice(result.value, ['INV-2024-0001']);
  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.customerId, 'C-001');
  assert.equal(issueResult.value.issueDate, '2024-01-15');
  assert.equal(issueResult.value.lines.length, 2);
  assert.equal(issueResult.value.lines[0].sku, 'DES-HOUR');
  assert.equal(issueResult.value.lines[1].sku, 'DEV-HOUR');
});

test('createInvoice accepts discountPercent on lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 12.5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 12.5);
});

test('createInvoice defaults discountPercent to 0', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice rejects invalid discountPercent', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: -5 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 101 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 'not a number' }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('lineDiscount calculates correctly', () => {
  const line = { qty: 10, unitPrice: 8500, discountPercent: 12.5 };
  const discount = lineDiscount(line);
  // line total = 85000 cents
  // discount = 85000 * 12.5 / 100 = 10625 cents
  assert.equal(discount, 10625);
});

test('lineDiscount defaults to 0 when discountPercent is missing', () => {
  const line = { qty: 10, unitPrice: 8500 };
  const discount = lineDiscount(line);
  assert.equal(discount, 0);
});

test('invoiceTotals includes discount in return value', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 12.5 }],
  };
  const totals = invoiceTotals(invoice);
  assert.ok('subtotal' in totals);
  assert.ok('discount' in totals);
  assert.ok('total' in totals);
});

test('invoiceTotals calculates discount correctly', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  const expected = 85000; // 10 * 8500
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.discount, 8500); // 10% of 85000
  assert.equal(totals.total, expected - 8500);
});

test('invoiceTotals with multiple lines and discounts', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, discountPercent: 10 },
      { qty: 10, unitPrice: 9500, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1Total = 5 * 8500; // 42500
  const line1Discount = 4250; // 10% of 42500
  const line2Total = 10 * 9500; // 95000
  const line2Discount = 19000; // 20% of 95000
  const subtotal = line1Total + line2Total;
  const discount = line1Discount + line2Discount;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.total, subtotal - discount);
});

test('invoiceTotals clamps total to 0 if discount exceeds subtotal', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 200 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 2000);
  assert.equal(totals.total, 0);
});

test('addLine accepts discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'DEV-HOUR', qty: 10, discountPercent: 15 });
  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines[1].discountPercent, 15);
});

test('addLine defaults discountPercent to 0', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'DEV-HOUR', qty: 10 });
  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines[1].discountPercent, 0);
});

test('addLine rejects invalid discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: 10, discountPercent: 150 }), { ok: false, error: 'DISCOUNT_INVALID' });
  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: 10, discountPercent: -5 }), { ok: false, error: 'DISCOUNT_INVALID' });
});

